    return { name: "home", status: "ok", detail: tr("doctor.home_absent", { home }) };
  if (stat.kind !== "dir")
    return { name: "home", status: "fail", detail: tr("doctor.home_not_dir", { home }), fix: tr("doctor.home_fix") };
